module ripple_carry_adder_sva (
    input logic       clk,
    input logic [3:0] A,
    input logic [3:0] B,
    input logic       Cin,
    input logic [3:0] Sum,
    input logic       Cout
);

    // External sampling clock; the DUT itself is combinational and has no reset.
    
    // Bit 0 sum is the XOR of A[0], B[0], and Cin.
    check_sum_bit0_xor: assert property (
        @(posedge clk)
        Sum[0] == (A[0] ^ B[0] ^ Cin)
    );

    // Bit 1 sum uses the carry generated by bit 0.
    check_sum_bit1_with_carry0: assert property (
        @(posedge clk)
        Sum[1] == (A[1] ^ B[1] ^ ((A[0] & B[0]) | (Cin & (A[0] | B[0]))))
    );

    // Bit 2 sum uses the carry generated by bit 1.
    check_sum_bit2_with_carry1: assert property (
        @(posedge clk)
        Sum[2] == (A[2] ^ B[2] ^ (
            (A[1] & B[1]) |
            (((A[0] & B[0]) | (Cin & (A[0] | B[0]))) & (A[1] | B[1]))
        ))
    );

    // Bit 3 sum uses the carry generated by bit 2.
    check_sum_bit3_with_carry2: assert property (
        @(posedge clk)
        Sum[3] == (A[3] ^ B[3] ^ (
            (A[2] & B[2]) |
            (((A[1] & B[1]) | (((A[0] & B[0]) | (Cin & (A[0] | B[0]))) & (A[1] | B[1]))) & (A[2] | B[2]))
        ))
    );

    // Sum matches the low 4 bits of A + B + Cin.
    check_sum_matches_low_addition: assert property (
        @(posedge clk)
        ({1'b0, Sum} == (({1'b0, A} + {1'b0, B} + Cin) & 5'h0F))
    );

    // MSB generate alone forces Cout high.
    check_cout_from_msb_generate: assert property (
        @(posedge clk)
        (A[3] & B[3]) |-> Cout
    );

    // Propagating the derived bit-2 carry through bit 3 forces Cout high.
    check_cout_from_msb_propagate: assert property (
        @(posedge clk)
        (
            ((A[2] & B[2]) |
             (((A[1] & B[1]) |
               (((A[0] & B[0]) | (Cin & (A[0] | B[0]))) & (A[1] | B[1]))) & (A[2] | B[2])))
            &
            (A[3] | B[3])
        ) |-> Cout
    );

    // The extra lower-carry term in the RTL also forces Cout high.
    check_cout_from_lower_carry_term: assert property (
        @(posedge clk)
        (
            ((A[1] & B[1]) |
             (((A[0] & B[0]) | (Cin & (A[0] | B[0]))) & (A[1] | B[1])))
            &
            ((A[0] & B[0]) | (Cin & (A[0] | B[0])))
        ) |-> Cout
    );

    // Cout matches the explicit RTL carry-out expression.
    check_cout_matches_rtl_logic: assert property (
        @(posedge clk)
        Cout == (
            (A[3] & B[3]) |
            (
                (
                    (A[2] & B[2]) |
                    (
                        (
                            (A[1] & B[1]) |
                            (((A[0] & B[0]) | (Cin & (A[0] | B[0]))) & (A[1] | B[1]))
                        ) &
                        (A[2] | B[2])
                    )
                ) &
                (A[3] | B[3])
            ) |
            (
                (
                    (A[1] & B[1]) |
                    (((A[0] & B[0]) | (Cin & (A[0] | B[0]))) & (A[1] | B[1]))
                ) &
                ((A[0] & B[0]) | (Cin & (A[0] | B[0])))
            )
        )
    );

endmodule